sop:
@f1 w.request.filler text=please
@r1 w.request.request act=change mood=do words="On second thought, a legend on every chart please"
@r1.t w.request.target request=$r1 family=page mode=existing determiner=definite fill=context
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing
@r1.u1 w.request.unread request=$r1 text="a legend on every chart" note=pref.app.legend value="a legend on every chart"
@r1.u2 w.request.unread request=$r1 text="second thought" note=drawn.detail

@r1 w.request.request act=change mood=do words="I prefer the values visible" predicate=prefer
