@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing
@r1.u1 w.request.unread request=$r1 text="value labels on" note=pref.app.labels value="value labels on"

@r1 w.request.request act=change mood=do words="Switch the default to a thicker stroke width" predicate=Switch
