@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=quantified fill=description sort=kid description="both kids"
@r1.c1 w.request.constraint request=$r1 on=size attribute=drawn.size words=bigger operator=delta phase=result step=more

@f1 w.request.filler text="rest of the scene unchanged"
@r1 w.request.request act=place mood=do words="let the bottom of the picture stay empty, always" predicate=let
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=definite fill=description sort=picture
